public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Perform a BFS from node 0 to find the shortest path to all nodes
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph.getNeighbors(node)) {
            if (dist[neighbor] == Integer.MAX_VALUE) {
                dist[neighbor] = dist[node] + 1;
                queue.add(neighbor);
            }
        }
    }

    // Calculate the minimum time required to collect all apples and return to node 0
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime = Math.max(minTime, dist[i] + dist[0]);
        }
    }

    return minTime;
}

